import type { ClientLike } from './_types.js'

/**
 * Input row for `upsertFromStripe`. Mirrors the `user_subscriptions` table
 * shape from migration 007 (post-MYT-42 round-7 fix). Caller (the webhook
 * handler) builds this from the Stripe event payload + tier resolution.
 */
export interface UpsertFromStripeRow {
  /** UUIDv7 generated by the caller (used only on first INSERT; preserved on UPDATE). */
  readonly id: string
  readonly user_id: string
  readonly stripe_subscription_id: string
  /** Closed enum enforced at write-time against backend/src/billing/lookup-keys.ts (no DB FK). */
  readonly tier_lookup_key: string
  /**
   * One of the 8 values admitted by the migration 007 CHECK constraint:
   * 'active'|'past_due'|'canceled'|'unpaid'|'incomplete'|'incomplete_expired'|'trialing'|'paused'.
   */
  readonly status: string
  readonly current_period_start: Date
  readonly current_period_end: Date
  readonly cancel_at_period_end: boolean
  /** Stripe's `cancel_at` is Unix seconds (`number | null`); converted via `to_timestamp($N)`. */
  readonly cancel_at: number | null
  /** Stripe's `cancellation_details` object; written as JSONB. */
  readonly cancellation_details: unknown
  /** From `event.created` (Unix seconds in Stripe; caller passes a Date). */
  readonly stripe_event_created_at: Date
}

/**
 * Row as returned from `user_subscriptions`. Mostly identical to the input
 * shape, but `cancel_at` reads back as `Date | null` (pg converts TIMESTAMPTZ
 * to Date), not the `number | null` Unix-seconds shape Stripe sends in. The
 * input interface uses `number | null` because that's what the webhook handler
 * has from the Stripe payload; the persisted row uses Date because that's
 * what pg gives us. Treat this asymmetry as intentional and don't unify.
 */
export interface UserSubscriptionRow {
  readonly id: string
  readonly user_id: string
  readonly stripe_subscription_id: string
  readonly tier_lookup_key: string
  readonly status: string
  readonly current_period_start: Date
  readonly current_period_end: Date
  readonly cancel_at_period_end: boolean
  readonly cancel_at: Date | null
  readonly cancellation_details: unknown
  readonly stripe_event_created_at: Date
  readonly created_at: Date
  readonly updated_at: Date
}

export interface MarkCanceledPayload {
  readonly cancel_at_period_end: boolean
  /** Unix seconds, per Stripe's payload shape; `null` when the field is absent. */
  readonly cancel_at: number | null
  /** Stripe's `cancellation_details` object at deletion time. */
  readonly cancellation_details: unknown
}

/**
 * Repository for the `user_subscriptions` table.
 *
 * Three methods, all required to run inside a caller-managed transaction:
 *   - `upsertFromStripe`: idempotent INSERT/UPDATE with strict-`>` stale-event filter.
 *   - `markCanceled`: status='canceled' UPDATE that PRESERVES the payload's
 *     `cancel_at_period_end` value (user-clicked vs Stripe-initiated distinction).
 *   - `getActiveForUser`: single-active-sub-per-user query for the balance + portal endpoints.
 */
export const userSubscriptions = {
  /**
   * Upsert a subscription row from a Stripe event.
   *
   * Single statement: `INSERT ... ON CONFLICT (stripe_subscription_id) DO UPDATE`
   * with a `WHERE excluded.stripe_event_created_at > user_subscriptions.stripe_event_created_at`
   * predicate (STRICT `>`, NOT `>=`, per spec round-3 fix §5.4.3 / Camembert I1 /
   * Stilton + Roquefort M5 round 3). Stale or same-second events are rejected as
   * a no-op UPDATE, which means the RETURNING clause yields zero rows in that
   * case. We then run a follow-up SELECT to return the canonical row state — the
   * existing row if rejected, the new row if applied. Caller (the webhook
   * handler) treats both as success; the row is what matters.
   *
   * Atomic against concurrent deliveries: handles checkout.session.completed
   * racing customer.subscription.created racing customer.subscription.updated.
   */
  async upsertFromStripe(tx: ClientLike, row: UpsertFromStripeRow): Promise<UserSubscriptionRow> {
    await tx.query(
      `INSERT INTO user_subscriptions (
         id, user_id, stripe_subscription_id, tier_lookup_key, status,
         current_period_start, current_period_end,
         cancel_at_period_end, cancel_at, cancellation_details,
         stripe_event_created_at
       )
       VALUES (
         $1, $2, $3, $4, $5,
         $6, $7,
         $8,
         CASE WHEN $9::BIGINT IS NULL THEN NULL ELSE to_timestamp($9::BIGINT)::TIMESTAMPTZ END,
         $10::JSONB,
         $11
       )
       ON CONFLICT (stripe_subscription_id) DO UPDATE
         SET user_id                 = EXCLUDED.user_id,
             tier_lookup_key         = EXCLUDED.tier_lookup_key,
             status                  = EXCLUDED.status,
             current_period_start    = EXCLUDED.current_period_start,
             current_period_end      = EXCLUDED.current_period_end,
             cancel_at_period_end    = EXCLUDED.cancel_at_period_end,
             cancel_at               = EXCLUDED.cancel_at,
             cancellation_details    = EXCLUDED.cancellation_details,
             stripe_event_created_at = EXCLUDED.stripe_event_created_at,
             updated_at              = now()
         WHERE EXCLUDED.stripe_event_created_at > user_subscriptions.stripe_event_created_at`,
      [
        row.id,
        row.user_id,
        row.stripe_subscription_id,
        row.tier_lookup_key,
        row.status,
        row.current_period_start,
        row.current_period_end,
        row.cancel_at_period_end,
        row.cancel_at,
        row.cancellation_details === null ? null : JSON.stringify(row.cancellation_details),
        row.stripe_event_created_at,
      ],
    )
    const got = await tx.query<UserSubscriptionRow>(
      `SELECT id, user_id, stripe_subscription_id, tier_lookup_key, status,
              current_period_start, current_period_end,
              cancel_at_period_end, cancel_at, cancellation_details,
              stripe_event_created_at, created_at, updated_at
         FROM user_subscriptions
         WHERE stripe_subscription_id = $1`,
      [row.stripe_subscription_id],
    )
    const found = got.rows[0]
    if (found === undefined) {
      // Defensive: the INSERT path always lands a row; ON CONFLICT DO UPDATE
      // (even when WHERE rejects) leaves the existing row in place. A missing
      // row here would mean a different transaction deleted it in the same
      // window, which violates Mythrun's "subscriptions are not hard-deleted"
      // invariant. Surface as a hard error rather than returning a sentinel.
      throw new Error(
        `userSubscriptions.upsertFromStripe: row missing after upsert for stripe_subscription_id=${row.stripe_subscription_id}`,
      )
    }
    return found
  },

  /**
   * Mark a subscription canceled.
   *
   * Behavior contract (spec §7.2 + round-2 Kraken C3 / Stilton M4 round 3):
   *   - Sets `status='canceled'`.
   *   - PRESERVES `cancel_at_period_end` from the payload — `true` for the
   *     user-clicked-Cancel-At-Period-End path, `false` for Stripe-initiated
   *     dunning cancellation. Collapsing this to a single value would erase
   *     the distinction needed for analytics + audit feed.
   *   - Converts `cancel_at` (Stripe Unix seconds, `number | null`) to TIMESTAMPTZ
   *     via `to_timestamp($N)`. Per round-5 type-correctness fix: spec prose said
   *     `string | null`, Stripe payload is `number | null`; we use the actual type.
   *   - Writes `cancellation_details` as JSONB.
   *
   * No-row-matched is a silent no-op (returns void). Per spec §5.4.4 line 667:
   * "If no row matches the stripe_subscription_id (Stripe-side test event,
   * deleted user, deletion-before-creation), log + COMMIT + 200." Logging is
   * the caller's responsibility — repo just succeeds.
   */
  async markCanceled(
    tx: ClientLike,
    stripe_subscription_id: string,
    payload: MarkCanceledPayload,
  ): Promise<void> {
    await tx.query(
      `UPDATE user_subscriptions
          SET status               = 'canceled',
              cancel_at_period_end = $2,
              cancel_at            = CASE WHEN $3::BIGINT IS NULL THEN NULL ELSE to_timestamp($3::BIGINT)::TIMESTAMPTZ END,
              cancellation_details = $4::JSONB,
              updated_at           = now()
        WHERE stripe_subscription_id = $1`,
      [
        stripe_subscription_id,
        payload.cancel_at_period_end,
        payload.cancel_at,
        payload.cancellation_details === null ? null : JSON.stringify(payload.cancellation_details),
      ],
    )
  },

  /**
   * Return the user's single active subscription, or `null` if there is none.
   *
   * "Active" excludes `canceled`, `incomplete_expired`, and `paused` per spec
   * §7.2. Mythrun's Customer Portal allowlist enforces one-active-sub-per-user
   * upstream, but `LIMIT 1` is belt-and-suspenders. Used by the §9 balance +
   * subscription endpoints.
   */
  async getActiveForUser(tx: ClientLike, user_id: string): Promise<UserSubscriptionRow | null> {
    const result = await tx.query<UserSubscriptionRow>(
      `SELECT id, user_id, stripe_subscription_id, tier_lookup_key, status,
              current_period_start, current_period_end,
              cancel_at_period_end, cancel_at, cancellation_details,
              stripe_event_created_at, created_at, updated_at
         FROM user_subscriptions
         WHERE user_id = $1
           AND status NOT IN ('canceled', 'incomplete_expired', 'paused')
         ORDER BY created_at DESC
         LIMIT 1`,
      [user_id],
    )
    return result.rows[0] ?? null
  },
}
